#!/usr/bin/env python3
"""Writes the config seed migration from data/game_config.json so client and server use the same numbers.
Run from the project root:  python3 backend/tools/gen_config_seed.py"""
import json, pathlib
root = pathlib.Path(__file__).resolve().parents[2]
cfg = json.loads((root / "data/game_config.json").read_text())
body = json.dumps(cfg, separators=(",", ":")).replace("'", "''")
out = root / "backend/supabase/migrations/20261104000003_seed_config.sql"
out.write_text(
    "-- GENERATED by backend/tools/gen_config_seed.py from data/game_config.json. Do not edit by hand.\n"
    f"insert into public.game_config (id, data) values (1, '{body}'::jsonb)\n"
    "on conflict (id) do update set data = excluded.data, updated_at = now();\n")
print("wrote", out)
